--region handler
function ActivityCakeShopBossRankMyCell:OnBtnDetailHandler()
    if isNull(self._rankInfo) then
        return
    end
    local isInList = false
    for _, rank in ipairs(self._rankInfo) do
        if checkString(rank.playerId) == self._playerDojo.playerId then
            isInList = true
            GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, rank.team, nil, nil, self._playerDojo.playerName)
        end
    end
    if not isInList then
        GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, {{}}, '', nil, self._playerDojo.playerName)
    end
end
--endregion handler

--region public
function ActivityCakeShopBossRankMyCell:Refresh(data, bossType, activityContentId)
    if not isNull(bossType) then
        self.bossType = checkNumber(bossType)
    end
    if not isNotNull(activityContentId) then
        self.activityContentId = checkNumber(activityContentId)
    else
        self.activityContentId = 1
    end
    self.rankData = data
    self._rankInfo = self.rankData.rank or self.rankData.rankInfo
    self._myRankInfo = self.rankData.playerRank
    self._playerDojo = self._playerComp:GetPlayerDojo()
    self._rankListVo = CfUtils.GetCf(AutoIds.IdSetting6249, "ActivityCakeBossRankVo", true)
    local function filterData(voList)
        local t = {}
        for i, v in pairs(voList) do
            if checkNumber(v.activityId) == self.activityContentId then
                table.insert(t, v)
            end
        end
        return t
    end
    if self.bossType == BossRankType.ParkMiniWorldBoss then
        self._rankListVo = CfUtils.GetCf(AutoIds.IdSetting6455, "ActivityCakeBossRankVo", true)
        self._rankListVo = filterData(self._rankListVo)
        ---@type MidFestivalBossParameterVo
        local parametersVo =  CfUtils.GetCfVo(AutoIds.IdSetting6452, "ActivityCakeBossParamsVo", 2)
        -- 排行榜最大显示的玩家数量
        self._rankShowCount = checkNumber(parametersVo.num)
    elseif self.bossType == BossRankType.ParkMiniWorldBossPartition then
        self._rankListVo = CfUtils.GetCf(AutoIds.IdSetting6466, "ActivityCakeBossRankVo", true)
        self._rankListVo = filterData(self._rankListVo)
        ---@type MidFestivalBossParameterVo
        local parametersVo = CfUtils.GetCfVo(AutoIds.IdSetting6452, "ActivityCakeBossParamsVo", 2)
        -- 排行榜最大显示的玩家数量
        self._rankShowCount = checkNumber(parametersVo.num)
    elseif self.bossType == BossRankType.JapaneseStory then
        self._rankListVo = CfUtils.GetCf(AutoIds.IdSetting6502, "JapaneseStoryBossRankRewardsVo", true)
        ---@type MidFestivalBossParameterVo
        local parametersVo =  CfUtils.GetCfVo(AutoIds.IdSetting6501, "JapaneseStoryBossParamsVo", 2)
        -- 排行榜最大显示的玩家数量
        self._rankShowCount = checkNumber(parametersVo.num)
    elseif self.bossType == BossRankType.MournBoss then
        self._rankListVo = CfUtils.GetCf(AutoIds.IdSetting6616, "JapaneseStoryBossRankRewardsVo", true)
        ---@type MidFestivalBossParameterVo
        local parametersVo =  CfUtils.GetCfVo(AutoIds.IdSetting6501, "JapaneseStoryBossParamsVo", 2)
        -- 排行榜最大显示的玩家数量
        self._rankShowCount = checkNumber(parametersVo.num)
    else
        ---@type ActivityCakeUtils
        local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
        ---@type ActivityCakeBossParamsVo
        local parametersVo = ActivityCakeUtils.GetActivityBossParamsVo(2)
        -- 排行榜最大显示的玩家数量
        self._rankShowCount = checkNumber(parametersVo.num)
    end
    self._rankText = checkString(self._myRankInfo.ranking)
    self._outOfRankList = false
    local myRankNum = checkNumber(self._myRankInfo.ranking)
    if bossType ~= BossRankType.MournBoss and bossType ~= BossRankType.ParkMiniWorldBoss and bossType ~= BossRankType.ParkMiniWorldBossPartition then
        if myRankNum > self._rankShowCount then
            self._outOfRankList = true
            myRankNum = self.rankData.percentageRank
            for _, vo in ipairs(self._rankListVo) do
                ---@type MidFestivalBossRankRewardVo
                local rankVo = vo
                if checkNumber(rankVo.type) == RankType.Percentage then
                    if myRankNum >= checkNumber(rankVo.upperLimit) and myRankNum <= checkNumber(rankVo.lowerLimit) then
                        self._rankText = rankVo.name
                    end
                end
            end
        end
    end
    
    self:RefreshUI()
end
--endregion public

--region private
function ActivityCakeShopBossRankMyCell:RefreshUI()
    -- 基本信息
    CfUtils.FillText(self.TxtName, self._playerDojo.playerName)
    CfUtils.FillText(self.TextLevel, "Lv." .. self._playerDojo.level)
    self._headScr:FreshAvatarFrame(self._playerDojo.playerAvatar, self._playerDojo.playerAvatarFrame)

    -- 排行信息
    if checkNumber(self._myRankInfo.damage) > 0  or  checkNumber(self._myRankInfo.hurt) > 0 then
        CfUtils.SetUISwitchImage(self.ImgRank, checkNumber(self._myRankInfo.ranking))
        CfUtils.FillText(self.Txtranking, self._rankText)
        CfUtils.SetActive(self.TxtNo, false)
        CfUtils.SetActive(self.RankNode, true)
    else
        -- 未造成伤害
        CfUtils.SetActive(self.TxtNo, true)
        CfUtils.SetActive(self.RankNode, false)
    end

    CfUtils.SetActive(self.ImgRank, not self._outOfRankList)

    -- 伤害和奖励
    CfUtils.FillText(self.TxtDamage, checkString(self._myRankInfo.damage))
    if string.isEmpty(checkString(self._myRankInfo.damage)) then
        CfUtils.FillText(self.TxtDamage, checkString(self._myRankInfo.hurt))
    end
    
    local rewards = {}
    local type = self._outOfRankList and RankType.Percentage or RankType.Digital
    local myRank = self._outOfRankList and self.rankData.percentageRank or self._myRankInfo.ranking
    for _, rank in ipairs(self._rankListVo) do
        ---@type ActivityCakeBossRankVo
        local rankVo = rank
        if checkNumber(myRank) >= rankVo.upperLimit and checkNumber(myRank) <= rankVo.lowerLimit and rankVo.type == type then
            local rewardCount = table.count(rankVo.reward)
            for i = 1, rewardCount do
                local reward = {
                    goodsId = rankVo.reward[i],
                    num = rankVo.rewardNum[i],
                }
                table.insert(rewards, reward)
            end
        end
    end
    CfUtils.SetActive(self.TextNoReward, table.count(rewards) == 0)
    self._rewardsScr:FreshBaseUI(rewards)

    CfUtils.SetActive(self.BtnDetails, not self._outOfRankList)

    CfUtils.SetActive(self.controller.gameObject, true)
end
--endregion private

--region get / set
--endregion get / set

return ActivityCakeShopBossRankMyCell
